sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //Determining Respective EndPoint from AdditionaAttributes

        var gr = new GlideRecord("x_hsb11_hsbc_mss_o_mss_event_outbound");
        gr.get(current.getValue('sys_id'));
        var payloadVal = JSON.parse(gr.request_body);
        var eventStatus = payloadVal.HEADER.eventstatus ? payloadVal.HEADER.eventstatus.toString() : "";
        var dynamicEndPoint;
        if (eventStatus != "") {
            switch (eventStatus) {

                case 'POST_CONTENT':
                    dynamicEndPoint = 'x_hsb11_mss_taskiz.taskizePostContentOutboundEndPoint';
                    break;

                case 'BUBBLE_UPDATE':
                    dynamicEndPoint = 'x_hsb11_mss_taskiz.taskizeUpdateBubbleOutboundEndPoint';
                    break;

                case 'ADD_PARTICIPANT':
                    dynamicEndPoint = 'x_hsb11_mss_taskiz.taskizeELAddBubbleParticipant_Outbound_EndPoint';
                    break;

                case 'ATTRIBUTE_UPDATE':
                    dynamicEndPoint = 'x_hsb11_mss_taskiz.taskizeUpdateBubbleOutboundEndPoint';
                    break;

                case 'BUBBLE_CREATE_WITH_ATTRIBUTE':
                    dynamicEndPoint = 'x_hsb11_mss_taskiz.taskizeELCreateNewBubble_Outbound_EndPoint';
                    break;
            }
        }

        //Determining Respective EndPoint from AdditionalAttributes

        var eventOutbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
        eventOutbound.get(current.getValue('sys_id'));

        var gcpOutboundToken = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_token');
        var endpoint = gs.getProperty(dynamicEndPoint); //dynamic EndPoint

        eventOutbound.state = 'Processsing';
        eventOutbound.update();

        var r = new sn_ws.RESTMessageV2('x_hsb11_mss_taskiz.Taskize Outbound API', 'Taskize');
        r.setEndpoint(endpoint);
        r.setRequestHeader('Authorization', 'Bearer ' + gcpOutboundToken);
        r.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

        var encodedPayload = gs.base64Encode(eventOutbound.request_body);
        var requestBody = 'data=' + encodeURIComponent(encodedPayload);

        r.setRequestBody(requestBody); //encoding to UTF- 8 since the content type is URL encoded

        //response
        var response = r.executeAsync();
        var responseBody = response.getBody();
        var statuscode = response.getStatusCode();

        if (statuscode == 200 || statuscode == 202) {
            eventOutbound.state = 'Processed';
        } else if ((statuscode.toString().charAt(0) == 4 || statuscode.toString().charAt(0) == 5) && (eventOutbound.retry_count < 3)) {
            eventOutbound.state = 'Ready to be sent';
            eventOutbound.retry_count += 1;
            var endSleep = new GlideDuration().getNumericValue() + 60000;
            while (new GlideDuration().getNumericValue() < endSleep) {
                //wait 
            }
            eventOutbound.update();
        } else {
            eventOutbound.state = 'Error';
			var grCase = new GlideRecord('x_hsb11_mss_taskiz_mss_taskize_case');
			grCase.get(current.document_id);
			if (grCase) {
				grCase.work_notes = 'Error from EventLayer API call:\n\nOperation - ' + eventStatus + '\n\nDetails - \n' + payloadVal + '\n\nActions - Please contact IT team';
				grCase.update();
			}
        }
        eventOutbound.response_body = responseBody;
        eventOutbound.update();


    } catch (e) {
        gs.info('Business rule MSS Custody Taskize EL Outbound errored with ' + e.message);
    }







})(current, previous);
